"""Pure: the skip patch, generated by code, never by the model.

Code finds the test's definition in the fetched file (exactly once, else no patch), inserts the
language's skip marker, and verifies the result by diffing: one added marker line (plus, where the
marker needs it, one added import), or one changed line for JavaScript / TypeScript. Anything else
aborts. Supported: Python, JavaScript / TypeScript, Go, Java / Kotlin, Rust.
"""

from __future__ import annotations

import difflib
import re
from dataclasses import dataclass

MAX_FILE_CHARS = 200_000
_PY, _JS, _GO, _JVM, _RS = "python", "javascript", "go", "jvm", "rust"
_LANGUAGES = {".py": _PY, ".js": _JS, ".jsx": _JS, ".ts": _JS, ".tsx": _JS, ".mjs": _JS, ".cjs": _JS,
              ".go": _GO, ".java": _JVM, ".kt": _JVM, ".rs": _RS}
_SAFE_REASON = re.compile(r"[^\w #:.,()/-]")
_IMPORT = re.compile(r"^(?:import|from)\s")


@dataclass(frozen=True)
class Patch:
    path: str
    original: str
    patched: str
    diff: str
    marker: str


def language(path: str) -> str:
    ext = path[path.rfind("."):].casefold() if "." in path else ""
    return _LANGUAGES.get(ext, "")


def reason_text(ticket: str, note: str = "") -> str:
    """`flaky: #12` (or `flaky: TBD`), plus an optional note; only safe characters, one line."""
    base = f"flaky: {ticket}"
    clean = _SAFE_REASON.sub("", " ".join(note.split()))[:80].strip()
    return f"{base} - {clean}" if clean else base


def make(path: str, content: str, name: str, ticket: str, note: str = "", scope: str = "") -> Patch | str:
    """The verified patch, or the reason there is none (shown to the user; no pull request then)."""
    lang = language(path)
    if not lang:
        return f"I can't add a skip marker to `{path}` (unsupported file type), so I'll offer the ticket only."
    if len(content) > MAX_FILE_CHARS:
        return f"`{path}` is too large for me to patch safely, so I'll offer the ticket only."
    lines = content.split("\n")
    hits = _find(lang, lines, name, scope)
    if len(hits) != 1:
        found = "isn't defined" if not hits else f"is defined {len(hits)} times"
        return f"`{name}` {found} in `{path}`, so I can't place one skip marker; I'll offer the ticket only."
    reason = reason_text(ticket, note)
    patched_lines, marker = _apply(lang, lines, hits[0], reason, path)
    patched = "\n".join(patched_lines)
    if not verify(lang, content, patched, marker):
        return f"The skip patch for `{path}` did not verify, so I'll offer the ticket only."
    return Patch(path, content, patched, unified_diff(path, content, patched), marker)


def _find(lang: str, lines: list[str], name: str, scope: str) -> list[int]:
    n = re.escape(name)
    pattern = {
        _PY: rf"^\s*(?:async\s+)?def\s+{n}\s*\(",
        _JS: rf"\b(?:it|test)\(\s*(['\"`]){n}\1",
        _GO: rf"^func\s+{n}\s*\(\s*\w+\s+\*testing\.T\s*\)",
        _JVM: rf"^\s*(?:(?:public|private|protected|internal|open)\s+)*(?:void|fun)\s+`?{n}`?\s*\(",
        _RS: rf"^\s*(?:pub\s+)?(?:async\s+)?fn\s+{n}\s*\(",
    }[lang]
    hits = [i for i, line in enumerate(lines) if re.search(pattern, line)]
    if len(hits) > 1 and scope and lang == _PY:
        hits = _in_class(lines, hits, scope)
    return hits


def _in_class(lines: list[str], hits: list[int], cls: str) -> list[int]:
    start = next((i for i, line in enumerate(lines) if re.match(rf"class\s+{re.escape(cls)}\b", line)), None)
    if start is None:
        return hits
    end = next((i for i in range(start + 1, len(lines)) if re.match(r"(?:class|def|async def)\s", lines[i])),
               len(lines))
    return [i for i in hits if start < i < end]


def _apply(lang: str, lines: list[str], at: int, reason: str, path: str) -> tuple[list[str], str]:
    line = lines[at]
    indent = line[: len(line) - len(line.lstrip())]
    if lang == _JS:
        changed = re.sub(r"\b(it|test)\(", r"\1.skip(", line, count=1)
        return [*lines[:at], changed, *lines[at + 1:]], changed
    if lang == _GO:
        marker = f'\tt.Skip("{reason}")'
        return [*lines[:at + 1], marker, *lines[at + 1:]], marker
    marker = indent + {_PY: f'@pytest.mark.skip(reason="{reason}")', _RS: f'#[ignore = "{reason}"]',
                       _JVM: f'@Disabled("{reason}")'}[lang]
    out = [*lines[:at], marker, *lines[at:]]
    if lang == _PY and not any(re.match(r"import pytest\b", x) for x in lines):
        out = _with_import(out, "import pytest")
    if lang == _JVM and not any("org.junit.jupiter.api.Disabled" in x for x in lines):
        semi = ";" if path.endswith(".java") else ""
        out = _with_import(out, f"import org.junit.jupiter.api.Disabled{semi}")
    return out, marker


def _with_import(lines: list[str], statement: str) -> list[str]:
    """After the last top-level import of the file's header, else at the top (after a package line)."""
    last = None
    for i, line in enumerate(lines):
        if _IMPORT.match(line):
            last = i
        elif re.match(r"(?:def|class|async def|@|fun|public|private)\b", line):
            break
    if last is None:
        last = next((i for i, line in enumerate(lines) if line.startswith("package ")), -1)
    return [*lines[:last + 1], statement, *lines[last + 1:]]


def verify(lang: str, original: str, patched: str, marker: str) -> bool:
    """One added marker line (plus one import for Python / JVM), or one changed line for JS. Nothing removed."""
    added, removed = _changes(original, patched)
    if lang == _JS:
        return len(added) == 1 and len(removed) == 1 and added[0] == marker
    if removed or marker not in added:
        return False
    extra = [a for a in added if a != marker]
    return len(added) == 1 or (len(added) == 2 and lang in (_PY, _JVM) and extra[0].startswith("import "))


def _changes(original: str, patched: str) -> tuple[list[str], list[str]]:
    diff = difflib.ndiff(original.split("\n"), patched.split("\n"))
    added, removed = [], []
    for line in diff:
        if line.startswith("+ "):
            added.append(line[2:])
        elif line.startswith("- "):
            removed.append(line[2:])
    return added, removed


def unified_diff(path: str, original: str, patched: str) -> str:
    lines = difflib.unified_diff(original.split("\n"), patched.split("\n"), f"a/{path}", f"b/{path}", lineterm="")
    return "\n".join(lines)
